    // painterly
    public static readonly string FloodAlgorithm =
        "FloodOutput FloodPropagate(FloodInput input)\n{\n    FloodOutput output;\n    output.distance = input.distance;\n    output.uv = input.floodUv;\n\n    [loop]\n    for (int x = -1; x <= 1; x++)\n    {\n        [loop]\n        for (int y = -1; y <= 1; y++)\n        {\n            if (x == 0 && y == 0)\n                continue;\n\n            float2 currentUv = input.sampleUv + float2(x, y) * input.texelSize;\n            currentUv = clamp(currentUv, 0, 0.999f);\n\n            float2 floodUv; float floodDist;\n            SampleFlood(currentUv, floodUv, floodDist);\n\n            float3 currentId; float unused;\n            SampleHash(floodUv, currentId, unused);\n\n            if (!IsSameCell(currentId, input.cellId))\n                continue;\n\n            [flatten]\n            if (floodDist < output.distance)\n            {\n                output.distance = floodDist;\n                output.uv = floodUv;\n            }\n        }\n    }\n\n    return output;\n}";

    // clouds
    public static readonly string CloudMarchLoop =
        "float4 CloudMarch(Ray ray, CloudParams cloudParams, LightParams lightParams)\n{\n    const float DET_THRESH = 1e-3; \n    \n    float transmittance = 1;\n    float3 accumulatedColor = float3(0, 0, 0);\n    \n    [loop]\n    for (int i = 0; i < ray.maxSteps; i++)\n    {\n        float3 position = ray.origin + ray.direction * ray.stepSize * i;\n        \n        float density = GetShapeDensity(position,\n            cloudParams.shapeNoiseScale,\n            cloudParams.noiseOffset,\n            cloudParams.coverage);\n\n        density *= GetHeightGradient(position.y,\n            cloudParams.heightExponent,\n            cloudParams.cloudHeight,\n            cloudParams.cloudDepth);\n\n        if (density > DET_THRESH)\n        {\n            ApplyDetailDensity(density,\n                position,\n                cloudParams.detailNoiseScale,\n                cloudParams.noiseOffset,\n                cloudParams.detailWeight);\n            \n            float originDensity = BeersDensity(ray.stepSize, density, cloudParams.absorption);\n            transmittance *= originDensity;\n\n            Ray lightRay = GetLightRay(position,\n                lightParams.lightDirection,\n                lightParams.rayLength);\n\n            float3 lightColor = LightMarch(lightRay, cloudParams, lightParams, density);\n            accumulatedColor += transmittance * (lightColor * density);\n            \n            if (transmittance < 0.01)\n                break;\n        }\n    }\n\n    float alpha = 1 - transmittance;\n    float3 cloudColor = lightParams.darkColor + accumulatedColor;\n    return float4(cloudColor, alpha);\n}";

    public static readonly string LightMarchLoop =
        "float3 LightMarch(Ray ray, CloudParams cloudParams, LightParams lightParams, float sampledDensity)\n{\n    float totalDensity = 0;\n    float maxHeight = cloudParams.cloudHeight + cloudParams.cloudDepth;\n    float previousDist = 0;\n\n    [unroll(MAX_LIGHT_STEPS)]\n    for (int i = 1; i <= MAX_LIGHT_STEPS; i++)\n    {\n        float t = (float)i / MAX_LIGHT_STEPS;\n        float currentDist = pow(t, 1.5) * ray.maxLength;\n\n        float stepLength = currentDist - previousDist;\n        previousDist = currentDist;\n\n        float3 position = ray.origin + ray.direction * currentDist;\n\n        if (position.y > maxHeight)\n            break;\n\n        float density = GetShapeDensity(position,\n            cloudParams.shapeNoiseScale,\n            cloudParams.noiseOffset,\n            cloudParams.coverage);\n        \n        density *= GetHeightGradient(position.y,\n            cloudParams.heightExponent,\n            cloudParams.cloudHeight,\n            cloudParams.cloudDepth);\n\n        totalDensity += density * stepLength;\n    }\n\n    float transmittance = BeersDensity(1.0, totalDensity, lightParams.absorption);\n    float powderMod = 1.0 - exp(-sampledDensity * 2.0);\n    float light = transmittance * powderMod * lightParams.phase;\n\n    return light * lightParams.lightColor;\n}";

    // grass
    public static readonly string GrassBurstJob =
        "[BurstCompile]\npublic struct FrustumCullJob : IJobParallelFor\n{\n    [ReadOnly] public NativeArray<float4> Planes;\n    [ReadOnly] public NativeArray<float3> TileCenters;\n    [ReadOnly] public NativeArray<float3> TileExtents;\n    [WriteOnly] public NativeArray<bool> Results;\n\n    public void Execute(int index)\n    {\n        float3 center = TileCenters[index];\n        float3 extent = TileExtents[index];\n\n        bool visible = true;\n\n        for (int i = 0; i < 6; i++)\n        {\n            float4 plane = Planes[i];\n            float3 normal = plane.xyz;\n            float distance = plane.w;\n\n            // Optimized AABB-Plane check\n            float r = math.dot(math.abs(normal), extent);\n            float d = math.dot(normal, center) + distance;\n\n            if (d < -r)\n            {\n                visible = false;\n                break;\n            }\n        }\n\n        Results[index] = visible;\n    }\n}";

    // karst
    public static readonly string FluxPass =
        "[numthreads(8,8,8)]\nvoid ResolveFlux (uint3 id : SV_DispatchThreadID) // 5\n{\n    if (ThreadOutOfBounds(id))\n        return;\n\n    KarstMaterial voxel = SampleVoxel(id, _FluxSource);\n    \n    if (!IsPermeable(voxel.density))\n        return;\n\n    Flow baseFlow = GetBaseFlow(voxel);\n    Flow outflow = GetTotalOutflow(id, voxel.acidConcentration, _FluxSource);\n    Flow inflow = GetTotalInflow(_FluxSource, id);\n    Flow netFlow = SubtractFlows(AddFlows(baseFlow, inflow), outflow);\n    \n    voxel.waterAmount = max(netFlow.waterFlow, 0.0f);\n    voxel.acidConcentration = ResolveAcidMass(voxel.waterAmount, netFlow.acidMass);\n    _FluxSource[id] = ResolveMaterial(voxel);\n}";

    // watercol sim
    public static readonly string KubelkaMunk =
        "private void CombineProperties(out Painting.PigmentProperties properties, out float thickness)\n{\n    properties = Painting.PigmentProperties(0, 0, 0, 0, 0);\n    thickness = 0;\n\n    [unroll(NUM_PIGMENTS)]\n    for (int i = 0; i < NUM_PIGMENTS; i++)\n    {\n        float currentThickness = thicknessReader.Read(i);\n\n        if (currentThickness < 1e-4f)\n            continue;\n\n        Painting.PigmentProperties combine = Painting.GetPigmentProperties((Painting.Pigment)i);\n        properties.K += combine.K * currentThickness;\n        properties.S += combine.S * currentThickness;\n        thickness += currentThickness;\n    }\n\n    if (thickness >= 1e-4f)\n    {\n        properties.K /= thickness;\n        properties.S /= thickness;\n    }\n}";

