    public static readonly string RayAligner =
        "public struct RayAligner<TVolume : IBoundingVolume>\n{\n    private TVolume volume;\n    private Ray ray;\n    private bool isFrontFace;\n\n    public __init(TVolume _volume,\n        bool _isFrontFace,\n        float3 _viewDirWS)\n    {\n        volume = _volume;\n        isFrontFace = _isFrontFace;\n        ray = Ray(_CameraPos, _viewDirWS, _ZBufferParams.x);\n    }\n\n    [mutating]\n    public Ray GetAlignedRay()\n    {\n        if(!volume.ShouldMarch(_CameraPos, isFrontFace, _ZBufferParams.x))\n        {\n            discard;\n        }\n\n        ray = volume.AlignWithVolume(ray);\n\n        if (ray.GetMaxLength() < 1e-3f)\n        {\n            discard;\n        }\n\n        return ray;\n    }\n}";

    public static readonly string PlanetSDF =
        "public struct Planet : SDF.SDF\n{\n    private float3 center;\n    private float scale;\n    private float invScale;\n    private float radius;\n    private float[5] hash;\n    private float3 normal;\n    private float3x3 basis;\n    private float4[4] colors;\n\n    public __init(float3 _center, \n        float _scale,\n        int _seed,\n        float4[4] _colors)\n    {\n        center = _center;\n        scale = _scale;\n        colors = _colors;\n        invScale = rcp(scale);\n        radius = 0.48f;\n\n        [unroll(5)]\n        for (int i = 0; i < 5; i++)\n        {\n            hash[i] = Noise.Functions.IntegerHash(_seed + PLANET_SEEDS[i]);\n        }\n\n        normal = normalize(float3(hash[2] - 0.5f, hash[3] - 0.5f, hash[4] - 0.5f));\n        basis = Math.GetOrthogonalBasis(normal);\n    }\n\n    public float Evaluate(SDF.MarchData data)\n    {\n        float3 localPos = (data.Position - center) * invScale;\n        float planetDist = Planet(localPos);\n        planetDist *= scale;\n        return planetDist;\n    }\n\n    private float Planet(float3 localPos)\n    {\n        float base = GetBase(localPos);\n        float ring = GetRing(localPos);\n\n        return SDF.Functions.Union(base, ring);\n    }\n\n    private float GetBase(float3 localPos)\n    {\n        float baseDist = SDF.Functions.Sphere(localPos, radius);\n        return baseDist;\n    }\n\n    private float GetRing(float3 localPos)\n    {\n        float plane = SDF.Functions.Box(mul(basis, localPos), float3(100, PLANET_RING_THICKNESS, 100));\n\n        float innerRingSize = lerp(INNER_RING_SIZE.x, INNER_RING_SIZE.y, hash[1]);\n        float outerRingSize = lerp(OUTER_RING_SIZE.x, OUTER_RING_SIZE.y, hash[0]);\n        outerRingSize = outerRingSize - innerRingSize < MIN_RING_THICKNESS ? 0 : outerRingSize;\n\n        float outerShape = SDF.Functions.Sphere(localPos, radius * outerRingSize);\n        SDF.FieldOut ringOuter = SDF.Functions.Intersection(plane, outerShape);\n        float innerShape = SDF.Functions.Sphere(localPos, radius * innerRingSize);\n\n        float ringDist = SDF.Functions.Subtraction(innerShape, ringOuter);\n        return ringDist;\n    }\n}\n";

