    public static readonly string SSSNFrequency =
        "struct Frequency\n{\n    float Max;\n    float Min;\n}\n\nprivate Frequency GetFrequency()\n{\n    Frequency frequency;\n\n    float2 dx = ddx(uv);\n    float2 dy = ddy(uv);\n\n    float E = dot(dx, dx);\n    float F = dot(dx, dy);\n    float G = dot(dy, dy);\n\n    float Q = E + G;\n    float R_sqr = (E * G) - (F * F); \n\n    float discriminantSqr = max(0.0f, Q * Q - 4.0f * R_sqr);\n    float discriminant = sqrt(discriminantSqr);\n\n    frequency.Max = sqrt((Q + discriminant) * 0.5f);\n    frequency.Min = sqrt((Q - discriminant) * 0.5f);\n    \n    return frequency;\n}";

    public static readonly string SSSNFractalData =
        "public struct FractalData\n{\n    public float LowLevel;\n    public float HighLevel;\n    public float SubLayer;\n}\n\npublic FractalData Solve()\n{\n    Frequency frequency = GetFrequency();\n\n    float spacing = frequency.Min;\n    spacing *= exp2(fractalScale);\n    float logDepth = log2(spacing);\n    float fractalStep = floor(logDepth);\n\n    FractalData data;\n    data.LowLevel = exp2(fractalStep);\n    data.HighLevel = exp2(fractalStep + 1);\n    data.SubLayer = logDepth - fractalStep;\n    return data;\n}";

    public static readonly string FractalSampler =
        "public interface INoise3DSampler\n{\n    public float Sample(float3 uvw);\n}\n\npublic struct FractalNoise<TNoiseSampler : INoise3DSampler>\n{\n    private static float BASE_SCALE = 9.0f;\n\n    TNoiseSampler noiseSampler;\n    float3 relativeWorldCoord;\n    float fractalScale;\n    \n    public __init(TNoiseSampler _noiseSampler,\n        float3 _positionWS,\n        float3 _transformCenter,\n        float _frequency)\n    {\n        noiseSampler = _noiseSampler;\n        relativeWorldCoord = _positionWS - _transformCenter;\n        fractalScale = BASE_SCALE / _frequency;\n    }\n\n    public float Solve(float3 offset = float3(0))\n    {\n        FractalData data = GetData();\n        float3 coord = relativeWorldCoord + offset;\n\n        float3 coordLow = coord / data.LowLevel;\n        float3 coordHigh = coord / data.HighLevel;\n        \n        float3 patternLow = frac(coordLow);\n        float turbulenceLow = noiseSampler.Sample(patternLow);\n        float3 patternHigh = frac(coordHigh);\n        float turbulenceHigh = noiseSampler.Sample(patternHigh);\n\n        return lerp(turbulenceLow, turbulenceHigh, data.SubLayer);\n    }\n\n    private FractalData GetData()\n    {\n        Noise.FractalSolver3D fractalSolver = Noise.FractalSolver3D(relativeWorldCoord, fractalScale);\n        Noise.FractalData fractalData = fractalSolver.Solve();\n        fractalData.LowLevel = max(1, fractalData.LowLevel);\n        fractalData.HighLevel = max(1, fractalData.HighLevel);\n\n        return fractalData;\n    }\n}";

    public static readonly string FractalScale =
        "module FractalScale;\n\n// Credits to RuneVision (Rune Skovbo Johansen): https://www.youtube.com/watch?v=HPqGaIMVuLs\n// this technique builds upon the fractal math used in the video\n\nnamespace Noise\n{\n    struct Frequency\n    {\n        float Max;\n        float Min;\n    }\n\n    public struct FractalData\n    {\n        public float LowLevel;\n        public float HighLevel;\n        public float SubLayer;\n    }\n\n    public struct FractalSolver3D\n    {\n        private float3 uvw;\n        private float fractalScale;\n\n        public __init(float3 _uvw,\n            float _fractalScale)\n        {\n            uvw = _uvw;\n            fractalScale = _fractalScale;\n        }\n\n        public FractalData Solve()\n        {\n            Frequency frequency = GetFrequency();\n\n            float spacing = frequency.Min;\n            spacing *= exp2(fractalScale);\n            float logDepth = log2(spacing);\n            float fractalStep = floor(logDepth);\n\n            FractalData data;\n            data.LowLevel = exp2(fractalStep);\n            data.HighLevel = exp2(fractalStep + 1);\n            data.SubLayer = logDepth - fractalStep;\n            return data;\n        }\n\n        private Frequency GetFrequency()\n        {\n            Frequency frequency;\n\n            float3 dx = ddx(uvw);\n            float3 dy = ddy(uvw);\n\n            float E = dot(dx, dx);\n            float F = dot(dx, dy);\n            float G = dot(dy, dy);\n\n            float Q = E + G;\n            float R_sqr = (E * G) - (F * F); \n\n            float discriminantSqr = max(0.0f, Q * Q - 4.0f * R_sqr);\n            float discriminant = sqrt(discriminantSqr);\n\n            frequency.Max = sqrt((Q + discriminant) * 0.5f);\n            frequency.Min = sqrt((Q - discriminant) * 0.5f);\n            \n            return frequency;\n        }\n    }\n\n    public struct FractalSolver2D\n    {\n        private float2 uv;\n        private float fractalScale;\n\n        public __init(float2 _uv,\n            float _fractalScale)\n        {\n            uv = _uv;\n            fractalScale = _fractalScale;\n        }\n\n        public FractalData Solve()\n        {\n            Frequency frequency = GetFrequency();\n\n            float spacing = frequency.Min;\n            spacing *= exp2(fractalScale);\n            float logDepth = log2(spacing);\n            float fractalStep = floor(logDepth);\n\n            FractalData data;\n            data.LowLevel = exp2(fractalStep);\n            data.HighLevel = exp2(fractalStep + 1);\n            data.SubLayer = logDepth - fractalStep;\n            return data;\n        }\n\n        private Frequency GetFrequency()\n        {\n            Frequency frequency;\n\n            float2 dx = ddx(uv);\n            float2 dy = ddy(uv);\n\n            float E = dot(dx, dx);\n            float F = dot(dx, dy);\n            float G = dot(dy, dy);\n\n            float Q = E + G;\n            float R_sqr = (E * G) - (F * F); \n\n            float discriminantSqr = max(0.0f, Q * Q - 4.0f * R_sqr);\n            float discriminant = sqrt(discriminantSqr);\n\n            frequency.Max = sqrt((Q + discriminant) * 0.5f);\n            frequency.Min = sqrt((Q - discriminant) * 0.5f);\n            \n            return frequency;\n        }\n    }\n}";

