    public static readonly string CangianteSpecular =
        "public float3 GetSpecularColor()\n{\n    float3 halfVec = normalize(light.GetDirection() + -viewDirection);\n    float NdotH = saturate(dot(normal, halfVec));\n    \n    float roughness = 1.0f - data.Smoothness;\n    float roughness2 = roughness * roughness * roughness * roughness;\n\n    float edge = lerp(0.99f, 1.0f, roughness2);\n    float mask = smoothstep(edge - 1e-4f, edge, NdotH);\n    \n    return mask * light.GetLightColor();\n}";
    
    public static readonly string PolygonalVoronoi =
        "// Credits to Inigo Quilez: https://iquilezles.org/articles/voronoilines/\n\npublic struct VoronoiPolygonal3D\n{\n    private float3 uvw;\n    private int seed;\n\n    public __init(float3 _uvw, int _seed)\n    {\n        uvw = _uvw;\n        seed = _seed;\n    }\n\n    public VoronoiResult3D Compute(float3 frequency = 1)\n    {\n        int3 scale = (int3)frequency;\n        float3 scaledCoord = uvw * scale;\n        int3 floorCoord = (int3)floor(scaledCoord);\n        float3 fracCoord = frac(scaledCoord);\n\n        int3 mb = 0;\n        float3 mr = 0;\n        float res = 8.0;\n        \n        int3 closestCellId = 0;\n        float3 closestRandomPoint = 0;\n\n        [unroll]\n        for (int z1 = -1; z1 <= 1; z1++)\n        {\n            [unroll]\n            for (int y1 = -1; y1 <= 1; y1++)\n            {\n                [unroll]\n                for (int x1 = -1; x1 <= 1; x1++)\n                {\n                    int3 b = int3(x1, y1, z1);\n                    int3 cellId = floorCoord + b;\n                    \n                    int3 wrappedCellId = (cellId % scale + scale) % scale;\n                    \n                    float3 randomPoint = Functions.Hash33(wrappedCellId + seed);\n                    float3 r = b + randomPoint - fracCoord;\n                    float d = dot(r, r);\n\n                    if (d < res)\n                    {\n                        res = d;\n                        mr = r;\n                        mb = b;\n                        closestCellId = cellId;\n                        closestRandomPoint = randomPoint;\n                    }\n                }\n            }\n        }\n\n        res = 8.0;\n\n        [unroll]\n        for (int z2 = -2; z2 <= 2; z2++)\n        {\n            [unroll]\n            for (int y2 = -2; y2 <= 2; y2++)\n            {\n                [unroll]\n                for (int x2 = -2; x2 <= 2; x2++)\n                {\n                    int3 b = mb + int3(x2, y2, z2);\n                    int3 cellId = floorCoord + b;\n                    \n                    int3 wrappedCellId = (cellId % scale + scale) % scale;\n                    \n                    float3 randomPoint = Functions.Hash33(wrappedCellId + seed);\n                    float3 r = b + randomPoint - fracCoord;\n                    float3 diff = r - mr;\n                    \n                    if (dot(diff, diff) > 0.00001)\n                    {\n                        float d = dot(0.5 * (mr + r), normalize(diff));\n                        res = min(res, d);\n                    }\n                }\n            }\n        }\n\n        VoronoiResult3D result = (VoronoiResult3D)0;\n        result.Distance = res;\n        result.Id = closestCellId;\n        result.Center = closestCellId + closestRandomPoint;\n\n        return result;\n    }\n}\n";

    public static readonly string ScrapeNoise =
        "public float GetScrapeNoise(float3 positionWS, \n    float3 transformCenter,\n    float3 normalWS,\n    float3 viewDirWS,\n    float hardness)\n{\n    Noise.FractalNoise<ScrapeNoiseSampler> scrapeNoise = Noise.FractalNoise<ScrapeNoiseSampler>(\n        ScrapeNoiseSampler(),\n        positionWS,\n        transformCenter,\n        0.9f);\n\n    float noise = scrapeNoise.Solve();\n    float threshold = Math.Remap(hardness, float2(0, 1), float2(0.6f, 0.45f));\n    float scrape = step(threshold, noise);\n\n    float mask = smoothstep(0.5f, 0.45f, (1.0f - saturate(dot(normalWS, -viewDirWS))));\n    return scrape * mask;\n}";

    public static readonly string CangianteFull =
        "import Lights;\n\nmodule WatercolorLit;\n\nnamespace WC\n{\n    public struct WCRDFData\n    {\n        public static float3 CANVAS_COLOR = float3(1.0f, 1.0f, 0.85f);\n\n        public float Cangiante;\n        public float Dilution;\n        public float DiluteArea;\n        public float Smoothness;\n        public float DarkIntensity;\n        public float LightColorIntensity;\n        public float Turbulence;\n\n        public __init(float cangiante,\n            float dilution,\n            float diluteArea,\n            float smoothness,\n            float darkIntensity,\n            float lightColorIntensity,\n            float turbulence)\n        {\n            Cangiante = cangiante;\n            Dilution = dilution;\n            DiluteArea = diluteArea;\n            Smoothness = smoothness;\n            DarkIntensity = darkIntensity;\n            LightColorIntensity = lightColorIntensity;\n            Turbulence = turbulence;\n        }\n    }\n    \n    public struct WCRDF\n    {\n        private WCRDFData data;\n        private float3 albedo;\n        private Light light;\n        private float3 normal;\n        private float3 viewDirection;\n        private float hardness;\n\n        public __init(WCRDFData _data,\n            float3 _albedo,\n            Light _light,\n            float3 _normal,\n            float3 _viewDirection,\n            float _hardness)\n        {\n            data = _data;\n            albedo = _albedo;\n            light = _light;\n            normal = _normal;\n            viewDirection = _viewDirection;\n            hardness = _hardness;\n        }\n\n        public float3 Shade()\n        {\n            float area = GetArea();\n            float3 cangianteColor = GetCangianteColor(area);\n            float3 specularColor = GetSpecularColor();\n\n            float3 wcrdf = cangianteColor + specularColor;\n            return lerp(wcrdf, WCRDFData::CANVAS_COLOR, hardness);\n        }\n\n        public float GetArea()\n        {\n            float NdotL = saturate(dot(normal, light.GetDirection()));\n            float area = (NdotL + (data.DiluteArea - 1.0f)) / data.DiluteArea;\n            return area + data.Turbulence;\n        }\n\n        public float3 GetCangianteColor(float area)\n        {\n            float3 pigment = saturate(albedo + data.Cangiante * area);\n            float3 base = lerp(WCRDFData::CANVAS_COLOR, light.GetLightColor(), data.LightColorIntensity);\n            float3 cangiante = data.Dilution * (area * (base - pigment)) + pigment;\n            float3 minColor = albedo * (1.0f - data.DarkIntensity);\n            return max(cangiante, minColor);\n        }\n\n        public float3 GetSpecularColor()\n        {\n            float3 halfVec = normalize(light.GetDirection() + -viewDirection);\n            float NdotH = saturate(dot(normal, halfVec));\n            \n            float roughness = 1.0f - data.Smoothness;\n            float roughness2 = roughness * roughness * roughness * roughness;\n\n            float edge = lerp(0.99f, 1.0f, roughness2);\n            float mask = smoothstep(edge - 1e-4f, edge, NdotH);\n\n            return mask * light.GetLightColor();\n        }\n    }\n}";

    public static readonly string DynamicCanvasUpdater =
        "class DynamicCanvasUpdater\n{\nprivate:\n    glm::vec2 accumulatedCanvasOffset = glm::vec2(0);\n    float panFraction;\n    glm::vec3 previousForward;\n    Material* material = nullptr;\n\npublic:\n    DynamicCanvasUpdater(Material* material,\n        const glm::vec3 forward,\n        float panPercentage)\n        : panFraction(panPercentage * 0.01f)\n        , previousForward(forward)\n        , material(material)\n    {\n    }\n\n    void Update(const glm::vec3 forward, const glm::vec3 up, const glm::vec3 right, const float fov)\n    {\n        UpdateOffset(forward, up, right, fov);\n        UpdateMaterial();\n    }\n\nprivate:\n    void UpdateOffset(const glm::vec3& forward, const glm::vec3& up, const glm::vec3& right, const float fov)\n    {\n        float x = glm::dot(previousForward, right);\n        float y = glm::dot(previousForward, up);\n        float z = glm::dot(previousForward, forward);\n\n        float deltaYaw = glm::degrees(std::atan2(-x, z));\n        float deltaPitch = glm::degrees(std::atan2(-y, z));\n\n        float uvDeltaX = (deltaYaw / fov) * panFraction;\n        float uvDeltaY = (deltaPitch / fov) * panFraction;\n\n        accumulatedCanvasOffset.x += uvDeltaX;\n        accumulatedCanvasOffset.y += uvDeltaY;\n\n        accumulatedCanvasOffset.x = std::fmod(accumulatedCanvasOffset.x, 1.0f);\n        accumulatedCanvasOffset.y = std::fmod(accumulatedCanvasOffset.y, 1.0f);\n\n        if (accumulatedCanvasOffset.x < 0.0f)\n            accumulatedCanvasOffset.x += 1.0f;\n        if (accumulatedCanvasOffset.y < 0.0f)\n            accumulatedCanvasOffset.y += 1.0f;\n\n        previousForward = forward;\n    }\n\n    void UpdateMaterial()\n    {\n        material->SetVector(\"_DynamicOffset\", glm::vec4(accumulatedCanvasOffset, 0, 0));\n    }\n};";

    public static readonly string CanvasPaperSampler =
        "public WC.PaperData SamplePaper(float2 offset)\n{\n    int width; int height; int levels;\n    _PaperTex.GetDimensions(0, width, height, levels);\n    float2 scale = (_ScreenParams.xy / float2(width, height)) * _PaperTiling;\n\n    float4 sample = _PaperTex.Sample(frac((uv + _DynamicOffset)) * scale + offset);\n    WC.PaperData data;\n    data.Height = sample.b;\n    data.Derivative = Math.PartialDerivative(sample.r, sample.g);\n    data.Derivative.Uncompress();\n    return data;\n}";

    public static readonly string PaperDistortion =
        "public float2 GetPaperDistortionOffset(Math.PartialDerivative paperDerivative,\n    float paperDistortionIntensity,\n    float pixelDistortion)\n{\n    return float2(paperDerivative.X, paperDerivative.Y) * paperDistortionIntensity * pixelDistortion;\n}";

    public static readonly string PaperGranulation =
        "public struct PaperGranulator\n{\n    private float paperInverse;\n    private float3 baseColor;\n    private float granulationIntensity;\n    private float pixelGranulation;\n\n    public __init(float _paperHeight,\n        float3 _baseColor,\n        float _granulationIntensity,\n        float _pixelGranulation)\n    {\n        paperInverse = 1.0f - _paperHeight;\n        baseColor = _baseColor;\n        granulationIntensity = _granulationIntensity;\n        pixelGranulation = _pixelGranulation;\n    }\n\n    public float3 Granulate()\n    {\n        float3 I = baseColor; \n        float p = 1.0 - paperInverse; \n        \n        float g = pixelGranulation * granulationIntensity; \n        float modulatedPiv = p * g; \n        float3 subtractionMode = I * saturate(I - modulatedPiv);\n        \n        float3 safeI = max(I, 0.0001);\n        float3 transmittanceMode = (1.0 - I) * pow(safeI, 1.0 + modulatedPiv);\n\n        return saturate(subtractionMode + transmittanceMode);\n    }\n}";

    public static readonly string EdgeBlurrer =
        "public struct EdgeBlurrer<TColorSampler : IColorSampler, TDepthSampler : IDepthSampler>\n{\n    private TColorSampler colorSampler;\n    private BlurDirection direction;\n    private int blurResolution;\n    private float blurSpread;\n    private float2 texelSize;\n\n    private TDepthSampler depthSampler;\n    private float depthThreshold;\n\n    public __init(TColorSampler _colorSampler,\n        BlurDirection _direction,\n        int _blurResolution,\n        float _blurSpread,\n        float2 _texelSize,\n        TDepthSampler _depthSampler,\n        float _depthTreshold)\n    {\n        colorSampler = _colorSampler;\n        direction = _direction;\n        blurResolution = _blurResolution;\n        blurSpread = _blurSpread;\n        texelSize = _texelSize;\n\n        depthSampler = _depthSampler;\n        depthThreshold = _depthTreshold;\n    }\n    \n    public float4 GetBlurredColor()\n    {\n        float centerGaussWeight = Functions.GaussWeight(0, blurSpread);\n\n        float4 colorSum = colorSampler.Sample(0) * centerGaussWeight;\n        float weightSum = centerGaussWeight;\n        \n        float2 offset = direction == BlurDirection::Horizontal \n            ? float2(texelSize.x, 0) : float2(0, texelSize.y);\n\n        float baseDepth = depthSampler.SampleLinear(0);\n\n        for (int i = -blurResolution; i <= blurResolution; i++)\n        {\n            if (i == 0)\n                continue;\n\n            float gaussWeight = Functions.GaussWeight(i, blurSpread);\n            float4 colorSample = colorSampler.Sample(offset * (float)i);\n\n            float depthSample = depthSampler.SampleLinear(offset * (float)i);\n            \n            float safeThreshold = max(depthThreshold, 0.0001);\n            float depthWeight = smoothstep(0, safeThreshold, abs(baseDepth - depthSample));\n\n            float weight = gaussWeight * depthWeight;\n\n            colorSum += colorSample * weight;\n            weightSum += weight;\n        }\n\n        return colorSum / max(weightSum, 0.0001);   \n    }\n}";
    
    public static readonly string TremorOffsetter =
        "public struct TremorOffsetter<TWatercolorProcessingSampler : IWatercolorProcessingSampler>\n{\n    private TWatercolorProcessingSampler wpSampler;\n    private float offsetIntensity;\n\n    public __init(TWatercolorProcessingSampler _wpSampler,\n        float _offsetIntensity)\n    {\n        wpSampler = _wpSampler;\n        offsetIntensity = _offsetIntensity;\n    }\n\n    public float2 GetOffset()\n    {\n        NormalsOffset normalsOffset = wpSampler.SampleNormalsOffset(0);\n        float2 sampledOffset = normalsOffset.Offset * offsetIntensity * float2(GetAspect(), 1);\n\n        return sampledOffset;\n    }\n}";

    public static readonly string ColorBleeder =
        "public struct ColorBleeder<TWaterColorProcessingSampler : IWatercolorProcessingSampler>\n{\n    private TWaterColorProcessingSampler wpSampler;\n    private float colorBleed;\n\n    public __init(TWaterColorProcessingSampler _wpSampler,\n        float _colorBleed)\n    {\n        wpSampler = _wpSampler;\n        colorBleed = _colorBleed;\n    }\n\n    public float3 GetColor(float2 uvOffset)\n    {\n        float3 base = wpSampler.SampleMain(uvOffset).rgb;\n        float3 blur = wpSampler.SampleBlurred(uvOffset).rgb;\n\n        return lerp(base, blur, saturate(colorBleed));\n    }\n}";

    public static readonly string GaussianBlur =
        "namespace Blur\n{\n    public interface IColorSampler\n    {\n        public float4 Sample(float2 offset);\n    }\n\n    public enum BlurDirection : int\n    {\n        Horizontal = 0,\n        Vertical = 1\n    }\n\n    public struct GaussianBlurrer<TColorSampler : IColorSampler>\n    {\n        private TColorSampler colorSampler;\n        private BlurDirection direction;\n        private int blurResolution;\n        private float blurSpread;\n        private float2 texelSize;\n\n        public __init(TColorSampler _colorSampler,\n            BlurDirection _direction,\n            int _blurResolution,\n            float _blurSpread,\n            float2 _texelSize)\n        {\n            colorSampler = _colorSampler;\n            direction = _direction;\n            blurResolution = _blurResolution;\n            blurSpread = _blurSpread;\n            texelSize = _texelSize;\n        }\n\n        public float4 GetBlurredColor()\n        {\n            float4 colorSum = (float4)0;\n            float weightSum = 1e-5f;\n            float2 offset = direction == BlurDirection::Horizontal \n                ? float2(texelSize.x, 0) : float2(0, texelSize.y);\n\n            for (int i = -blurResolution; i <= blurResolution; i++)\n            {\n                float gaussWeight = Functions.GaussWeight(i, blurSpread);\n                float4 sample = colorSampler.Sample(offset * (float)i);\n\n                colorSum += sample * gaussWeight;\n                weightSum += gaussWeight;\n            }\n\n            return colorSum / weightSum;\n        }\n    }\n\n    namespace Functions\n    {\n        public float GaussWeight(float offset, float spread)\n        {\n            float x = offset;\n            float sigmaSqu = spread * spread;\n\t        return (1.0f / sqrt(2.0f * PI * sigmaSqu)) * exp(-(x * x) / (2 * sigmaSqu));\n        }\n    }\n}";

    public static readonly string EdgeDarkening =
        "public struct EdgeDarkener<TWaterColorProcessingSampler : IWatercolorProcessingSampler>\n{\n    private TWaterColorProcessingSampler wpSampler;\n    private float3 bleededColor;\n    private float edgeDarkening;\n\n    public __init(TWaterColorProcessingSampler _wpSampler,\n        float3 _bleededColor,\n        float _edgeDarkening)\n    {\n        wpSampler = _wpSampler;\n        bleededColor = _bleededColor;\n        edgeDarkening = _edgeDarkening;\n    }\n\n    public float3 ComputeEdgeDarkening(float2 offset)\n    {\n        float3 base = wpSampler.SampleMain(offset).rgb;\n        float3 blur = wpSampler.SampleBlurred(offset).rgb;\n        float3 DoG = abs(base - blur);\n        float exponent = 1.0f + edgeDarkening * max(DoG.r, max(DoG.g, DoG.b));\n        return pow(bleededColor, exponent);\n    }\n}";

    public static readonly string EnhancementCangiante =
        "float3 CangianteSimple(float3 color, float height)\n{\n    float3 base = WC::WCRDFData::CANVAS_COLOR;\n\n    float3 cangiante = 0.05f * ((1.0f - height * 0.4f) * (base - color)) + color;\n    float3 minColor = color * 0.5f;\n\n    return max(cangiante, minColor);\n}";

    public static readonly string EnhancementVibrancy =
        "namespace Functions\n{\n    public float Luminance(float3 rgb)\n    {\n        return dot(float3(0.2126, 0.7152, 0.0722), rgb);\n    }\n\n    public float Saturation(float3 rgb)\n    {\n        float cMin = min(min(rgb.r, rgb.g), rgb.b);\n        float cMax = max(max(rgb.r, rgb.g), rgb.b);\n        float delta = cMax - cMin;\n        return cMax == 0.0 ? 0.0 : (delta / cMax);\n    }\n}\n\npublic float3 ApplyVibrance(float3 rgb, float vibrance)\n{\n    float luminance = Functions.Luminance(rgb);\n    float saturation = Functions.Saturation(rgb);\n\n    float vibranceVal = vibrance * (1.0f - saturation);\n    return lerp(float3(luminance), rgb, 1.0f + vibranceVal);\n}";
